mapper.select:
SELECT d.meter_id AS meterId, d.usage_date AS usageDate, ROUND(SUM(d.total_usage), 2) AS totalUsage FROM electricity_daily_usage d WHERE d.deleted = 0
AND d.meter_id = #{meterId}
AND d.usage_date >= DATE_SUB( (SELECT COALESCE(MAX(usage_date), CURDATE()) FROM electricity_daily_usage WHERE deleted = 0), INTERVAL #{days} DAY) GROUP BY d.meter_id, d.usage_date ORDER BY d.meter_id ASC, d.usage_date ASC
